import sys

def main():
    import sys
    import math

    def max_operations(a):
        max_ops = 0
        for num in a:
            ops = 0
            while num % 2 == 0:
                num //= 2
                ops += 1
            while num % 3 == 0:
                num //= 3
                ops += 1
            if num == 1:
                max_ops = max(max_ops, ops)
            else:
                return -1
        return max_ops

